// 验证辅导请求
const requestData = $input.first().json;

// 验证必需字段
if (!requestData.sessionId || !requestData.parsedData) {
  throw new Error('Invalid coaching request data');
}

// 生成唯一请求ID
const requestId = `coach_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// 返回处理后的数据
return {
  json: {
    ...requestData,
    requestId,
    receivedAt: new Date().toISOString(),
    workflow: 'coaching-generate'
  }
};

// 生成面试指南
const { sessionId, parsedData, preferences } = $input.first().json;

// 模拟生成面试指南的过程
// 实际应该调用AI服务生成内容
const guide = {
  sections: [
    {
      title: '面试前准备',
      content: '详细的面试前准备工作...',
      tips: ['研究公司背景', '了解职位要求', '准备常见问题答案'],
      examples: ['自我介绍示例', '项目描述示例']
    },
    {
      title: '面试中技巧',
      content: '面试过程中的注意事项...',
      tips: ['保持眼神交流', '使用STAR法则回答问题']
    }
  ]
};

return {
  json: {
    sessionId,
    step: 'guide-generated',
    progress: 30,
    guide
  }
};

// 构建问题库
const sessionId = $input.first().json.sessionId;
const parsedData = $input.first().json.parsedData || $('generate-guide').first().json.parsedData;

// 基于分析结果生成问题
const questionBank = [
  {
    id: 'q001',
    question: '请介绍一下你的项目经验',
    category: 'experience',
    difficulty: 'medium',
    modelAnswer: {
      structure: ['项目背景', '我的角色', '遇到的挑战', '解决方案', '项目成果'],
      keyPoints: ['量化成果', '突出技术难点', '展示团队协作'],
      exampleResponse: '在我负责的XX项目中...',
      pitfalls: ['过于技术化', '没有量化成果']
    },
    followUpQuestions: ['你在项目中遇到的最大挑战是什么？']
  },
  {
    id: 'q002',
    question: '你为什么想加入我们公司？',
    category: 'motivation',
    difficulty: 'easy',
    modelAnswer: {
      structure: ['公司认同', '职位匹配', '个人发展'],
      keyPoints: ['展示对公司的了解', '连接个人职业规划'],
      exampleResponse: '我对贵公司的XX产品印象深刻...',
      pitfalls: ['过于泛泛而谈', '只谈薪资福利']
    }
  }
];

return {
  json: {
    sessionId,
    step: 'questions-built',
    progress: 60,
    questionBank
  }
};

// 设计模拟面试
const sessionId = $input.first().json.sessionId;

const mockInterview = {
  rounds: [
    {
      type: 'self-introduction',
      duration: 5,
      questions: ['请简单介绍一下你自己'],
      evaluationCriteria: ['表达清晰度', '经验相关性', '职业规划']
    },
    {
      type: 'technical',
      duration: 20,
      questions: ['谈谈你最熟悉的技术栈', '如何解决技术难题'],
      evaluationCriteria: ['技术深度', '解决问题能力', '学习能力']
    },
    {
      type: 'behavioral',
      duration: 15,
      questions: ['描述一次团队合作的经历', '如何处理工作压力'],
      evaluationCriteria: ['团队协作', '情商', '抗压能力']
    }
  ],
  scoreCard: [
    {
      criterion: '技术能力',
      weight: 0.4,
      description: '评估技术深度和广度'
    },
    {
      criterion: '沟通能力',
      weight: 0.3,
      description: '评估表达清晰度和逻辑性'
    },
    {
      criterion: '解决问题的能力',
      weight: 0.3,
      description: '评估分析和解决问题的能力'
    }
  ]
};

return {
  json: {
    sessionId,
    step: 'mock-designed',
    progress: 80,
    mockInterview
  }
};

// 制定行动计划
const sessionId = $input.first().json.sessionId;
const preferences = $input.first().json.preferences || { timeframe: 7 };

const actionPlan = {
  dailyTasks: [
    {
      day: 1,
      tasks: ['研究公司信息', '准备自我介绍'],
      estimatedTime: 2,
      resources: ['公司官网', 'LinkedIn']
    },
    {
      day: 2,
      tasks: ['熟悉简历项目', '准备项目介绍'],
      estimatedTime: 3,
      resources: ['项目文档', 'STAR方法指南']
    },
    {
      day: 3,
      tasks: ['练习常见问题', '准备行为面试例子'],
      estimatedTime: 2,
      resources: ['问题库', 'STAR模板']
    }
  ],
  milestones: [
    {
      day: 3,
      goal: '完成所有常见问题准备',
      checkpoints: ['行为问题', '技术问题', '项目介绍']
    },
    {
      day: 7,
      goal: '完成模拟面试',
      checkpoints: ['自我介绍流畅', '技术问题熟练', '行为问题自然']
    }
  ],
  resources: [
    {
      type: 'article',
      title: '面试技巧指南',
      url: 'https://example.com/interview-guide',
      description: '详细的面试技巧文章'
    },
    {
      type: 'video',
      title: '面试礼仪视频',
      url: 'https://example.com/interview-etiquette',
      description: '面试礼仪和注意事项'
    }
  ]
};

return {
  json: {
    sessionId,
    step: 'plan-created',
    progress: 100,
    actionPlan
  }
};

// 汇总所有生成的内容
const sessionId = $input.first().json.sessionId;
const guide = $('generate-guide').first().json.guide;
const questionBank = $('build-questions').first().json.questionBank;
const mockInterview = $('design-mock').first().json.mockInterview;
const actionPlan = $('create-plan').first().json.actionPlan;

const coachingResult = {
  sessionId,
  generatedAt: new Date().toISOString(),
  coaching: {
    materials: {
      guide,
      questionBank,
      mockInterview,
      actionPlan
    },
    metadata: {
      wordCount: 5000,
      estimatedReadTime: 25,
      lastUpdated: new Date().toISOString(),
      version: '1.0.0'
    }
  }
};

return {
  json: {
    success: true,
    sessionId,
    status: 'completed',
    data: coachingResult,
    timestamp: new Date().toISOString()
  }
};

// 错误处理
const error = $input.first().json;

return {
  json: {
    success: false,
    sessionId: error.sessionId || '',
    status: 'failed',
    error: {
      code: 'WORKFLOW_ERROR',
      message: error.message || 'Unknown error occurred'
    },
    timestamp: new Date().toISOString()
  }
};
